      "apiAccess": {
        "type": "string",
        "const": "full",
        "default": "full"
      },
      "caCertificate": {
        "type": "string",
        "maxLength": 20000,
        "x-widget": "textarea",
        "title": "CA certificate (PEM)",
        "description": "Only for a private CA."
      }
